class Animal {
    String name;
    Animal(String name) { this.name = name; }
    void speak() { System.out.println(name + " makes a sound."); }
}

class Dog extends Animal {
    Dog(String name) { super(name); }

    @Override
    void speak() { System.out.println(name + " barks!"); }
}

class Cat extends Animal {
    Cat(String name) { super(name); }

    @Override
    void speak() { System.out.println(name + " meows!"); }
}

public class Main {
    public static void main(String[] args) {
        Animal a1 = new Dog("Rex");
        Animal a2 = new Cat("Whiskers");
        a1.speak(); // Rex barks!
        a2.speak(); // Whiskers meows!
    }
}

interface Shape {
    double area();
    double perimeter();
}

class Circle implements Shape {
    double radius;
    Circle(double r) { this.radius = r; }

    public double area() { return Math.PI * radius * radius; }
    public double perimeter() { return 2 * Math.PI * radius; }
}

class Rectangle implements Shape {
    double w, h;
    Rectangle(double w, double h) { this.w = w; this.h = h; }

    public double area() { return w * h; }
    public double perimeter() { return 2 * (w + h); }
}

public class Main {
    public static void main(String[] args) {
        Shape s1 = new Circle(5);
        Shape s2 = new Rectangle(4, 6);
        System.out.printf("Circle area: %.2f%n", s1.area());
        System.out.printf("Rectangle area: %.2f%n", s2.area());
    }
}

public class ExceptionDemo {
    static int divide(int a, int b) {
        if (b == 0) throw new ArithmeticException("Cannot divide by zero!");
        return a / b;
    }

    public static void main(String[] args) {
        try {
            System.out.println(divide(10, 2));  // 5
            System.out.println(divide(10, 0));  // throws
        } catch (ArithmeticException e) {
            System.out.println("Error: " + e.getMessage());
        } finally {
            System.out.println("Done.");
        }

        // Parsing exception
        try {
            int n = Integer.parseInt("abc");
        } catch (NumberFormatException e) {
            System.out.println("Invalid number format.");
        }
    }
}

import java.util.ArrayList;
import java.util.HashMap;

public class Collections {
    public static void main(String[] args) {
        // ArrayList
        ArrayList<String> fruits = new ArrayList<>();
        fruits.add("Apple");
        fruits.add("Banana");
        fruits.add("Mango");
        fruits.remove("Banana");
        for (String f : fruits) System.out.println(f);

        // HashMap
        HashMap<String, Integer> scores = new HashMap<>();
        scores.put("Alice", 95);
        scores.put("Bob", 82);
        scores.put("Carol", 88);
        System.out.println("Alice: " + scores.get("Alice"));
        for (String key : scores.keySet()) {
            System.out.println(key + " -> " + scores.get(key));
        }
    }
}
